import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
import stringToColor from 'flarum/common/utils/stringToColor';
export const EXT = 'ernestdefoe-corkboard';
export const t = (key, params = {}) => app.translator.trans(`${EXT}.forum.${key}`, params);
export const tx = (key, params = {}) => extractText(t(key, params));

/** What a failed request does: tells the person why (unless it's a quiet read), and rejects. */
const onError = quiet => quiet ? () => {} : error => {
  app.alerts.show({
    type: 'error'
  }, errorText(error));
  throw error;
};

/** Corkboard's actions that aren't a resource's create, read, update or delete, under /api/corkboard. */
export function call(method, path, body, params, quiet = false) {
  return app.request({
    method,
    url: `${app.forum.attribute('apiUrl')}/corkboard${path}`,
    body,
    params,
    errorHandler: onError(quiet)
  });
}

/** Corkboard's JSON:API resources: corkboard-boards, -columns, -labels, -cards, -comments, -checklist-items, -members. */

function resource(method, type, id, body, params, quiet = false) {
  return app.request({
    method,
    url: `${app.forum.attribute('apiUrl')}/corkboard-${type}${id ? `/${id}` : ''}`,
    body,
    params,
    errorHandler: onError(quiet)
  });
}

/**
 * Create (no id), update or delete one of them. Resolves with what the change answers with (its
 * `view`: the card as the board draws it, the whole board, a page of comments…), or null for a delete.
 */
export function write(method, type, id, attributes = {}, quiet = false) {
  const body = method === 'DELETE' ? undefined : {
    data: {
      type: `corkboard-${type}`,
      ...(id ? {
        id: String(id)
      } : {}),
      attributes
    }
  };
  return resource(method, type, id, body, undefined, quiet).then(answer => answer?.data?.attributes?.view ?? null);
}

/** A board or a card as the page draws it (its `view`). Quiet: the caller shows what went wrong. */
export function read(type, id) {
  return resource('GET', type, id, undefined, undefined, true).then(answer => answer.data.attributes.view);
}

/** One item of a list, its id a number again. */
const item = d => ({
  id: Number(d.id),
  ...d.attributes
});

/** A tile's people come with it; the pages keep them as ids and a users map, as the board does. */
function tiles(list, users) {
  return list.map(tile => {
    tile.people.forEach(p => users[p.id] = p);
    return {
      ...tile,
      people: tile.people.map(p => p.id)
    };
  });
}

/** A page of the boards list: a tab, a search, a project's boards; the pinned row on the first page. */
export function boardList(filter, page = 0) {
  const set = Object.fromEntries(Object.entries(filter).filter(([, value]) => value !== undefined && value !== ''));
  return resource('GET', 'boards', null, undefined, {
    filter: set,
    page: {
      offset: page * 30
    }
  }, true).then(doc => {
    const users = {};
    return {
      boards: tiles(doc.data.map(item), users),
      pinned: tiles(doc.meta?.pinned || [], users),
      more: !!doc.links?.next,
      users
    };
  });
}

/** A card in a list: as the board draws it, where it is, and its people themselves. */

/**
 * A page of corkboard-cards: { mine: 1, owned?, done? }, { dueWithin: days, board? },
 * { column, after? } or { board, archived: 1 }. The people come with each card; they're also
 * gathered in a users map, as the board keeps them.
 */
export function cardList(filter, limit = 50) {
  const set = Object.fromEntries(Object.entries(filter).filter(([, value]) => value !== undefined && value !== ''));
  return resource('GET', 'cards', null, undefined, {
    filter: set,
    page: {
      limit
    }
  }, true).then(doc => {
    const users = {};
    const cards = doc.data.map(d => {
      const card = item(d);
      (card.people || []).forEach(p => users[p.id] = p);
      return card;
    });
    return {
      cards,
      total: doc.meta?.page?.total ?? cards.length,
      more: !!doc.links?.next,
      users
    };
  });
}
/** The built-in templates (a forum attribute) and the forum's template boards (a boards tab). */
export function templateList() {
  const builtIn = app.forum.attribute('corkboardTemplates') || [];
  return boardList({
    tab: 'templates'
  }).then(({
    boards
  }) => ({
    builtIn,
    custom: boards.map(b => ({
      key: String(b.id),
      title: b.title,
      color: b.color,
      columns: b.columns || []
    }))
  }));
}

/** A card's comments older than one already shown, as the card draws them. */
export function commentList(card, before) {
  return resource('GET', 'comments', null, undefined, {
    filter: {
      card,
      before
    }
  }).then(doc => {
    const users = {};
    const comments = doc.data.map(d => {
      const {
        user,
        cardId,
        ...comment
      } = item(d);
      if (user) users[user.id] = user;
      return comment;
    });
    return {
      comments,
      more: !!doc.links?.next,
      users
    };
  });
}

/** The sentence for an error answer: our own refusals carry it, the rest are core's. */
export function errorText(error) {
  const detail = error?.response?.errors?.[0]?.detail;
  if (detail && error?.status === 422) return String(detail);
  if (error?.status === 0) return extractText(app.translator.trans('core.lib.error.network_message'));
  if (error?.status === 403) return extractText(app.translator.trans('core.lib.error.permission_denied_message'));
  if (error?.status === 404) return tx('error.gone');
  return extractText(app.translator.trans('core.lib.error.generic_message'));
}
/** A team group's name; a hidden one is only named to moderators. */
export const groupName = group => group ? group.name ?? tx('hidden_group') : '';
export const PRIORITIES = ['none', 'low', 'normal', 'high', 'urgent'];
export const ROLES = ['viewer', 'commenter', 'editor', 'manager'];
export const VISIBILITIES = ['public', 'members', 'team', 'private'];
export const VISIBILITY_ICON = {
  public: 'fas fa-globe',
  members: 'fas fa-user-check',
  team: 'fas fa-users',
  private: 'fas fa-lock'
};

/** A person's picture, or their initials on their colour (core's own colour for a name). */
export const Avatar = {
  view(vnode) {
    const {
      user,
      size = 24,
      ring
    } = vnode.attrs;
    const style = {
      width: `${size}px`,
      height: `${size}px`,
      fontSize: `${Math.round(size * 0.4)}px`
    };
    const cls = 'CorkboardAvatar' + (ring ? ' CorkboardAvatar--ring' : '');
    if (!user) return m("span", {
      className: cls + ' CorkboardAvatar--gone',
      style: style,
      "aria-hidden": "true"
    });
    if (user.avatarUrl) return m("img", {
      className: cls,
      style: style,
      src: user.avatarUrl,
      alt: "",
      loading: "lazy",
      title: user.name
    });
    const initials = user.name.split(/\s+/).map(w => w[0] || '').join('').slice(0, 2).toUpperCase();
    return m("span", {
      className: cls,
      style: {
        ...style,
        background: `#${stringToColor(user.name)}`
      },
      title: user.name,
      "aria-hidden": "true"
    }, initials);
  }
};
const MONTH = {
  month: 'short',
  day: 'numeric'
};

/** "Fri, Nov 14", "Dec 1", "Nov 14, 5:00 PM" and how urgent it is. */
export function due(card) {
  if (!card.dueAt) return null;
  const at = new Date(card.dueAt);
  const now = Date.now();
  const days = (at.getTime() - now) / 86400000;
  const sameYear = at.getFullYear() === new Date().getFullYear();
  const opts = {
    ...MONTH,
    ...(sameYear ? {} : {
      year: 'numeric'
    }),
    ...(days >= 0 && days < 7 ? {
      weekday: 'short'
    } : {})
  };
  if (!card.dueAllDay) Object.assign(opts, {
    hour: 'numeric',
    minute: '2-digit'
  });
  const text = at.toLocaleString(app.translator.getLocale() || undefined, card.dueAllDay ? {
    ...opts,
    timeZone: 'UTC'
  } : opts);
  const state = card.completedAt ? 'done' : at.getTime() < now ? 'late' : days <= 2 ? 'soon' : 'later';
  return {
    text,
    state
  };
}

/** "12 min ago", "3 d ago", then a date. */
export function ago(iso) {
  if (!iso) return '';
  const s = Math.max(1, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (s < 60) return tx('time.now');
  if (s < 3600) return tx('time.minutes', {
    count: Math.floor(s / 60)
  });
  if (s < 86400) return tx('time.hours', {
    count: Math.floor(s / 3600)
  });
  if (s < 86400 * 7) return tx('time.days', {
    count: Math.floor(s / 86400)
  });
  return new Date(iso).toLocaleDateString(app.translator.getLocale() || undefined, MONTH);
}

/** Text that sits on a colour: dark on light labels, white on the rest. */
export function onColor(hex) {
  const h = (hex || '#888888').replace('#', '');
  const [r, g, b] = [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) / 255).map(c => c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
  const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return lum > 0.4 ? '#1f2733' : '#ffffff';
}
export function boardUrl(board, card) {
  const id = board.slug ? `${board.id}-${board.slug}` : String(board.id);
  return app.route('corkboard.board', {
    id
  }) + (card ? `?card=${card}` : '');
}

/** The lazy chunk: every page and dialog, fetched the first time one is needed. */
export const ui = () => import(/* webpackChunkName: 'forum/components', webpackMode: 'lazy-once' */ './components');